*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--sans)}body{min-height:100vh;background-image:radial-gradient(ellipse at 34% 4%,rgba(73,98,61,.17),transparent 40%),radial-gradient(ellipse at 85% 70%,rgba(31,67,51,.1),transparent 40%)}button{color:inherit;font:inherit;cursor:pointer}button:focus-visible{outline:2px solid var(--lime);outline-offset:3px}.app-shell{width:min(1450px,100%);margin:auto;padding:0 40px 30px}.topbar{height:74px;border-bottom:1px solid rgba(148,165,146,.13);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center;color:var(--text);font:700 23px var(--display);letter-spacing:-1.3px;text-decoration:none}.brand-mark{font-size:30px;line-height:1;color:var(--lime);text-shadow:0 0 18px #b5ed685c}.brand-dot{color:var(--lime)}.top-center{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:24px}.season-pill,.top-level{font:500 10px var(--mono);letter-spacing:1.15px;color:#a6b0a5}.season-pill{display:flex;align-items:center;gap:8px}.live-dot,.status-pulse{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px #c8f36b9c}.top-level{color:#d8e0d4}.top-level b{color:#647064}.icon-btn{width:38px;height:38px;border-radius:50%;border:1px solid #354037;background:#171e18;color:#b9c4b8;font-size:17px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 305px;gap:38px;padding-top:24px}.play-column{min-width:0}.level-heading{padding:0 3px 14px}.eyebrow,.panel-kicker{display:flex;gap:9px;align-items:center;color:var(--lime);font:500 10px var(--mono);letter-spacing:1.2px}.eyebrow-line{width:18px;height:1px;background:var(--lime);opacity:.65}.title-line{display:flex;align-items:center;gap:14px;margin-top:8px}.level-heading h1{font:600 clamp(26px,3vw,38px)/1.1 var(--display);letter-spacing:-1.4px;margin:0}.level-heading p{font-size:13px;color:#9da99c;margin:8px 0 0}.level-badge{border:1px solid #3b473c;border-radius:100px;padding:5px 9px;color:#b6c0b3;font:10px var(--mono);letter-spacing:.5px;white-space:nowrap}.board-wrap{position:relative;background:linear-gradient(145deg,#172018,#131a15 65%);border:1px solid #29342b;border-radius:13px;overflow:hidden;box-shadow:0 15px 45px #00000028,inset 0 1px #ffffff08}.board-wrap:before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(185,212,175,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(185,212,175,.025) 1px,transparent 1px);background-size:35px 35px;mask-image:linear-gradient(to bottom,black,transparent 88%);pointer-events:none}.board-topline,.board-bottomline{position:absolute;z-index:2;left:19px;right:19px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.board-topline{top:15px}.board-status,.move-counter,.board-bottomline{font:9px var(--mono);letter-spacing:.75px;color:#99a598}.board-status{display:flex;align-items:center;gap:8px}.status-pulse{width:6px;height:6px}.move-counter{color:#6e7c70}.move-counter b{font-size:12px;color:#e4ebdf;margin-left:7px}.board-bottomline{bottom:14px;justify-content:center;gap:25px;font-size:8px;color:#869286}.board-bottomline span{display:flex;align-items:center;gap:6px}.legend-start{width:7px;height:7px;background:#ffe69b;border-radius:50%;box-shadow:0 0 8px #ffe69b88}.legend-path{width:12px;height:2px;background:#b9ed74;box-shadow:0 0 5px #b9ed74}.legend-goal{font-style:normal;color:var(--lime);font-size:12px}.board-wrap canvas{display:block;width:100%;height:390px;touch-action:none;position:relative;z-index:1}.canvas-hint{position:absolute;z-index:2;right:18px;top:15px;color:#718072;font:9px var(--mono);letter-spacing:.2px}.canvas-hint span{color:var(--lime);font-size:12px;margin-right:5px}.controls-row{display:flex;align-items:center;justify-content:space-between;gap:17px;padding:16px 3px 0}.dpad{width:120px;height:112px;position:relative;flex:0 0 120px}.move-key{position:absolute;width:37px;height:34px;background:#202a21;border:1px solid #334036;color:#dce7d7;border-radius:7px;font-size:17px;line-height:1;transition:background .15s,transform .15s}.move-key:hover,.action-btn:hover,.utility-btn:hover{background:#29352a;border-color:#53654d}.move-key:active,.action-btn:active,.utility-btn:active{transform:scale(.94)}.key-up{top:0;left:41px}.key-left{top:38px;left:2px}.key-down{top:38px;left:41px}.key-right{top:38px;left:80px}.dpad-center{position:absolute;bottom:2px;left:34px;color:#657263;font:8px var(--mono);letter-spacing:1px}.action-controls{display:flex;gap:8px;flex:1;min-width:0}.action-btn{height:56px;display:flex;align-items:center;gap:9px;padding:0 11px;background:#1a221b;border:1px solid #303d31;border-radius:9px;text-align:left;flex:1;min-width:0;transition:.16s}.action-icon{font-size:20px;color:var(--lime);line-height:1}.action-btn>span:nth-child(2){min-width:0;display:grid;gap:3px}.action-btn b{font-size:11px;font-weight:600;white-space:nowrap}.action-btn small{font-size:9px;color:#879386;white-space:nowrap}.action-btn kbd{margin-left:auto;color:#657162;background:#212a22;border:1px solid #303c31;border-radius:4px;padding:3px 4px;font:8px var(--mono);white-space:nowrap}.rotate-btn .action-icon{font-size:23px}.shift-btn .action-icon{font-size:20px}.utility-controls{display:flex;gap:7px}.utility-btn{height:48px;min-width:46px;padding:0 7px;border:1px solid #2f3b31;border-radius:8px;background:#171f19;color:#b6c2b5;font-size:20px;display:grid;place-items:center;line-height:1;transition:.16s}.utility-btn span{font:8px var(--mono);color:#788578}
.side-panel{display:flex;flex-direction:column;gap:13px;padding-top:1px}.mission-card,.level-card,.marble-card{border:1px solid #2c382e;background:linear-gradient(145deg,#19221b,#161d17);border-radius:11px;padding:17px}.panel-kicker{font-size:9px;letter-spacing:1.1px;color:#98a795}.panel-kicker span{color:var(--lime)}.mission-card h2,.panel-head h2{font:600 17px var(--display);letter-spacing:-.3px;margin:12px 0 7px}.mission-card>p{font-size:11px;line-height:1.6;color:#9ba79b;margin:0;min-height:36px}.mission-progress{margin-top:17px}.progress-copy{display:flex;justify-content:space-between;color:#748174;font:9px var(--mono);letter-spacing:.5px}.progress-copy b{color:#b4c3b0;font-weight:400}.progress-track{height:4px;border-radius:8px;background:#2c372d;margin-top:8px;overflow:hidden}.progress-track i{height:100%;display:block;width:0;background:linear-gradient(90deg,#a8d75c,#d7f389);box-shadow:0 0 9px #b8ed7060;transition:width .5s}.objective{height:38px;margin-top:15px;background:#202a20;border:1px solid #303d30;border-radius:7px;display:flex;align-items:center;gap:9px;padding:0 9px;font-size:10px;color:#bbc8b9}.objective-icon{color:var(--lime);font-size:14px}.objective-check{margin-left:auto;color:#74816e;font-size:15px}.objective.done{border-color:#54633a;background:#283323}.objective.done .objective-check{color:var(--lime)}.level-card{padding:16px 15px 11px}.panel-head{display:flex;justify-content:space-between;align-items:center}.panel-head h2{margin:7px 0 0}.tiny-link{border:0;background:transparent;color:#879485;font:9px var(--mono);letter-spacing:.6px;padding:6px 0}.tiny-link span{color:var(--lime);font-size:12px}.level-list{display:grid;gap:4px;margin-top:12px}.level-item{width:100%;height:37px;display:flex;align-items:center;gap:10px;border:1px solid transparent;background:transparent;border-radius:6px;padding:0 8px;text-align:left;color:#879286;transition:.15s}.level-item:hover:not(:disabled){background:#202a21}.level-item.active{background:#252f23;border-color:#465438;color:#edf2e8}.level-number{font:10px var(--mono);color:#657365;width:19px}.level-item.active .level-number{color:var(--lime)}.level-item.locked{opacity:.42;cursor:not-allowed}.level-name{font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.level-stars{margin-left:auto;color:#707a65;font-size:10px;letter-spacing:1px;white-space:nowrap}.level-item.completed .level-stars{color:#c4e87e}.level-item.active .level-stars{color:#b7d76e}.marble-card{padding:15px}.edit-marble{width:25px;height:25px;border:1px solid #344035;background:#202a21;border-radius:6px;color:#aebaa9}.skin-preview{width:100%;margin-top:13px;height:54px;padding:0 10px;display:flex;align-items:center;gap:10px;background:#202a21;border:1px solid #303d31;border-radius:8px;text-align:left}.mini-marble{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;font-size:18px;background:radial-gradient(circle at 30% 25%,#fff5ce,#f3b657 42%,#c06a28 100%);box-shadow:0 3px 6px #0008,inset -4px -4px 7px #783f3944}.skin-name{display:grid;gap:3px}.skin-name b{font:600 11px var(--display)}.skin-name small{font:8px var(--mono);letter-spacing:.6px;color:#788679}.skin-chevron{margin-left:auto;font-size:20px;color:#84917f}.skin-swatches{display:flex;gap:8px;margin:12px 3px 0}.swatch{width:17px;height:17px;border-radius:50%;border:2px solid #1b241c;box-shadow:0 0 0 1px #536052;cursor:pointer;transition:.15s}.swatch.active{box-shadow:0 0 0 1px var(--lime);transform:scale(1.13)}.side-footer{display:flex;justify-content:space-between;margin-top:auto;padding:3px 4px 0;color:#58665a;font:8px var(--mono);letter-spacing:.6px}.side-footer b{color:var(--lime);font-size:7px;margin-left:4px}.toast{position:fixed;z-index:15;bottom:26px;left:50%;transform:translate(-50%,20px);padding:11px 16px;border:1px solid #526440;border-radius:8px;background:#202b20;box-shadow:0 10px 30px #0008;color:#e5efdc;font-size:12px;opacity:0;pointer-events:none;transition:.22s}.toast.show{opacity:1;transform:translate(-50%,0)}
.modal-backdrop{position:fixed;inset:0;background:#0b100dd9;backdrop-filter:blur(7px);z-index:30;display:grid;place-items:center;padding:20px}.modal-backdrop[hidden]{display:none}.modal{width:min(390px,100%);position:relative;text-align:center;padding:34px 30px 28px;background:linear-gradient(145deg,#202a20,#171e18);border:1px solid #45533f;border-radius:16px;box-shadow:0 25px 100px #000a}.modal-close{position:absolute;right:14px;top:12px;width:30px;height:30px;border:0;background:transparent;color:#9ba895;font-size:24px}.modal-emblem{font-size:40px;color:var(--lime);text-shadow:0 0 25px #c8f36b66}.modal .panel-kicker{justify-content:center;margin-top:8px}.modal h2{font:600 26px var(--display);margin:11px 0 6px;letter-spacing:-.7px}.modal p{font-size:12px;color:#9aa79a;margin:0}.star-row{font-size:21px;color:#bce56b;letter-spacing:5px;margin:18px 0 20px;text-shadow:0 0 14px #c5ed6655}.primary-btn,.secondary-btn{width:100%;height:45px;border:0;border-radius:7px;background:var(--lime);color:#20291b;font:700 10px var(--mono);letter-spacing:1px}.primary-btn span{margin-left:8px;font-size:15px}.secondary-btn{height:35px;background:transparent;color:#aab7a8;font:10px var(--sans);letter-spacing:0;margin-top:7px}.primary-btn:hover{background:#d6ff83}.modal.next-mode .modal-emblem{color:#f4cd74}.modal.next-mode .primary-btn{background:#d6e0d1}
@media(max-width:1050px){.app-shell{padding:0 24px 24px}.game-layout{grid-template-columns:minmax(0,1fr) 275px;gap:22px}.controls-row{gap:10px}.dpad{transform:scale(.88);transform-origin:left center;margin-right:-10px}.action-btn{padding:0 8px;gap:6px}.action-btn kbd{display:none}.action-btn small{font-size:8px}.side-panel{gap:10px}}
@media(max-width:760px){.app-shell{padding:0 14px max(16px,env(safe-area-inset-bottom))}.topbar{height:57px}.brand{font-size:21px}.brand-mark{font-size:27px}.top-center{position:static;transform:none;margin-left:auto;margin-right:13px}.season-pill{display:none}.top-level{font-size:9px}.icon-btn{width:33px;height:33px}.game-layout{display:flex;flex-direction:column;gap:14px;padding-top:15px}.level-heading{padding-bottom:12px}.level-heading h1{font-size:28px}.level-heading p{font-size:12px;margin-top:6px}.board-wrap{border-radius:10px}.board-wrap canvas{height:clamp(260px,48vh,390px)}.board-topline,.board-bottomline{left:12px;right:12px}.board-topline{top:11px}.canvas-hint{top:30px;left:12px;right:auto;font-size:8px}.board-bottomline{bottom:10px;gap:13px;font-size:7px}.controls-row{padding-top:10px;display:grid;grid-template-columns:104px 1fr;gap:8px 6px}.dpad{width:104px;height:98px;transform:scale(.82);transform-origin:top left;margin-right:-18px;margin-bottom:-16px}.action-controls{display:grid;grid-template-columns:1fr 1fr;gap:6px}.action-btn{height:43px;padding:0 7px;gap:6px;border-radius:7px}.action-icon{font-size:17px}.action-btn b{font-size:10px}.action-btn small{font-size:8px}.action-btn kbd{display:none}.shift-btn{grid-column:1 / -1}.utility-controls{grid-column:1/-1;justify-content:flex-end;margin-top:-3px}.utility-btn{height:36px;min-width:70px;display:flex;align-items:center;justify-content:center;gap:6px;font-size:17px}.utility-btn span{font-size:8px}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:9px}.mission-card{grid-column:1/-1;padding:13px 14px}.mission-card h2{font-size:15px;margin:8px 0 4px}.mission-card>p{min-height:0;font-size:10px}.mission-progress{margin-top:11px}.objective{margin-top:10px;height:32px}.level-card,.marble-card{padding:12px}.panel-head h2{font-size:15px}.level-list{gap:1px;margin-top:8px}.level-item{height:30px;padding:0 5px;gap:6px}.level-number{font-size:9px;width:17px}.level-name{font-size:9px}.level-stars{font-size:9px}.tiny-link{font-size:8px}.skin-preview{margin-top:9px;height:46px;padding:0 7px;gap:7px}.mini-marble{width:29px;height:29px;font-size:16px}.skin-name b{font-size:10px}.skin-name small{font-size:7px}.skin-swatches{gap:7px;margin-top:9px}.swatch{width:14px;height:14px}.side-footer{grid-column:1/-1;padding-top:2px}.toast{bottom:calc(18px + env(safe-area-inset-bottom));white-space:nowrap}}
@media(max-width:380px){.app-shell{padding-left:10px;padding-right:10px}.level-heading h1{font-size:25px}.level-badge{font-size:8px;padding:4px 7px}.board-wrap canvas{height:250px}.board-bottomline{gap:9px}.action-btn small{display:none}.action-btn{height:38px}.mission-card{padding:11px}.side-panel{gap:7px}.level-card,.marble-card{padding:10px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}

